-- Demo data for local development: one restaurant with a small sample menu.
-- Placeholder content, not a real restaurant's menu.
-- Safe to run again: fixed ids, and every insert skips rows that already exist.
-- No BEGIN/COMMIT here; run it with psql -1 (see CLAUDE.md).

INSERT INTO restaurants (id, name, timezone)
VALUES ('00000000-0000-4000-8000-000000000001', 'Demo Kitchen', 'America/Los_Angeles')
ON CONFLICT (id) DO NOTHING;

-- Placeholder tax rate: 875 basis points = 8.75%.
INSERT INTO settings (restaurant_id, tax_rate_bps)
VALUES ('00000000-0000-4000-8000-000000000001', 875)
ON CONFLICT (restaurant_id) DO NOTHING;

-- Placeholder hours: 07:00 to 23:00 every day (weekday 0 = Monday).
INSERT INTO opening_hours (restaurant_id, weekday, opens_at, closes_at)
SELECT '00000000-0000-4000-8000-000000000001', weekday, '07:00', '23:00'
FROM generate_series(0, 6) AS weekday
ON CONFLICT (restaurant_id, weekday, opens_at) DO NOTHING;

